INSERT INTO repair_symptom_relation (repair_preset_id, symptom_preset_id, created_at)
SELECT rp.id, sp.id, '2025-07-01 10:00:00'
FROM repair_preset rp, symptom_preset sp
WHERE rp.name = N'노트북 전원부 점검/수리'
  AND sp.product_category = N'노트북'
  AND sp.name = N'전원 불량'
