-- Repair 증상 프리셋 / 수리 작업(프리셋) 연결 더미 데이터
INSERT INTO repair_symptom_preset (repair_id, symptom_preset_nam)
SELECT r.id, N'와이파이 끊김'
FROM repair r
JOIN as_reception a ON a.id = r.as_reception_id
WHERE a.reception_number = 'AS-251112-00001'
  AND NOT EXISTS (
    SELECT 1 FROM repair_symptom_preset rsp
    WHERE rsp.repair_id = r.id AND rsp.symptom_preset_nam = N'와이파이 끊김'
  );

INSERT INTO repair_work (repair_id, repair_preset_name, work_name,
                       created_at, updated_at, created_by, updated_by)
SELECT r.id, N'노트북 와이파이 모듈 교체', N'노트북 와이파이 모듈 교체',
       '2025-11-12 19:00:22', '2025-11-12 19:00:22',
       (SELECT id FROM member WHERE email = 'technician001@fixgo.com'),
