SELECT 'fixgo-received-AS-251112-00001-963e5dd7', 'RECEIVED', 'customer001@naver.com', N'[FixGo] A/S 접수 완료 안내', N'고객님의 A/S 접수가 정상적으로 완료되었습니다.',
       'FAILED', 1, 'MailSendException', NULL, '2025-11-12 09:10:22', '2025-11-12 09:10:22',
       (SELECT id FROM member WHERE email = 'receptionist001@fixgo.com'), a.id
FROM as_reception a
WHERE a.reception_number = 'AS-251112-00001'
  AND NOT EXISTS (SELECT 1 FROM notification_log n WHERE n.event_key = 'fixgo-received-AS-251112-00001-963e5dd7');

