INSERT INTO part_stock_history (part_id, repair_part_usage_id, movement_type, quantity_delta, reason, created_at, created_by)
SELECT p.id, u.id, 'OUT', u.quantity, N'수리 사용 출고', '2025-11-12 19:00:22',
       (SELECT id FROM member WHERE email = 'technician001@fixgo.com')
FROM repair_part_usage u
JOIN repair_work rw ON rw.id = u.repair_work_id
JOIN repair r ON r.id = rw.repair_id
JOIN as_reception a ON a.id = r.as_reception_id
JOIN part p ON p.id = u.part_id
WHERE a.reception_number = 'AS-251112-00001'
  AND rw.repair_preset_name = N'노트북 와이파이 모듈 교체'
  AND p.name = N'사자북 공용 와이파이 모듈 [SZB-ALL-WIFI]'
  AND NOT EXISTS (
    SELECT 1 FROM part_stock_history h WHERE h.repair_part_usage_id = u.id AND h.movement_type = 'OUT'
  );

